// reclaim chunks no file references anymore
async function collectGarbage() {
  const chunks = await chunkStore.listAll();
  for (const c of chunks) {
    const refs = await refcounts.get(c.hash);   // current reference count
    if (refs === 0) {
      await chunkStore.delete(c.hash);           // hard-delete the bytes
    }
  }
}
